"""Metric layer: token-level (pooled) AUROC/AUPRC and document-level AUROC/AUPRC
obtained by mean aggregation of token scores (paper Eq. 3)."""
import numpy as np
from sklearn.metrics import average_precision_score, roc_auc_score, roc_curve


def auroc(y, s):
    y = np.asarray(y).astype(int)
    if y.min() == y.max():
        return float("nan")
    return float(roc_auc_score(y, s))


def auprc(y, s):
    """sklearn's average_precision == area under the precision-recall curve
    (identical to auc(recall, precision) from the authors' eval.py)."""
    y = np.asarray(y).astype(int)
    if y.min() == y.max():
        return float("nan")
    return float(average_precision_score(y, s))


def token_level(scores, labels):
    scores = np.asarray(scores, dtype=np.float64)
    labels = np.asarray(labels).astype(int)
    return {"auroc": auroc(labels, scores), "auprc": auprc(labels, scores),
            "n_tokens": int(len(labels)), "n_positive_tokens": int(labels.sum())}


def doc_level(scores, labels, slices):
    """Eq. 3: s_doc = mean of its token scores.  `slices` are (start, end) row ranges
    into `scores`/`labels` for each test document, in document order."""
    scores = np.asarray(scores, dtype=np.float64)
    labels = np.asarray(labels).astype(int)
    ds, dl = [], []
    for a, b in slices:
        if b <= a:
            continue
        ds.append(scores[a:b].mean())
        dl.append(int(labels[a:b].max()))
    ds, dl = np.array(ds), np.array(dl)
    return {"auroc": auroc(dl, ds), "auprc": auprc(dl, ds),
            "n_docs": int(len(ds)), "n_positive_docs": int(dl.sum()),
            "doc_scores": ds.tolist(), "doc_labels": dl.tolist()}


def sanity_check_metric_plumbing(rng=None):
    """Verify our AUROC/AUPRC agree with sklearn on synthetic data (plumbing check)."""
    rng = np.random.default_rng(0)
    y = (rng.random(500) < 0.05).astype(int)
    s = rng.normal(size=500) + 3.0 * y
    out = {
        "auroc_matches_sklearn": abs(auroc(y, s) - roc_auc_score(y, s)) < 1e-12,
        "auprc_matches_sklearn": abs(auprc(y, s) - average_precision_score(y, s)) < 1e-12,
        "perfect_ranker_auroc": auroc([0, 0, 1, 1], [0.1, 0.2, 0.8, 0.9]),
        "inverted_ranker_auroc": auroc([0, 0, 1, 1], [0.9, 0.8, 0.2, 0.1]),
    }
    return out

